import React, { useState } from "react";
import { BrowserRouter as Router, Switch, Route } from "react-router-dom";
import Header from "./components/Header";
import Info from "./components/info";
import Form from "./components/form";
import Place from "./components/place";
import Footer from "./components/Footer";
import { Login } from "./pages/Login";
import { Register } from "./pages/Register";
import "./App.css";

const API_KEY = "e5832fe7fa724f039e8a644e5697a808";

const App = () => {
  const [currentForm, setCurrentForm] = useState('login');
  const [state, setState] = useState({
    temp: undefined,
    ip: undefined,
    city: undefined,
    country_name: undefined,
    state_prov: undefined,
    hostname: undefined,
    error: undefined,
  });

  const toggleForm = (formName) => {
    setCurrentForm(formName);
  }

  const gettingPlace = async (e) => {
    e.preventDefault();
    const Ip = e.target.elements.ip.value;
    const api_url = await fetch(`https://api.ipgeolocation.io/ipgeo?apiKey=${API_KEY}&ip=${Ip}&appid`);
    const data = await api_url.json();
    console.log(data);

    if (Ip) {
      setState({
        ip: data.ip,
        city: data.city,
        country_name: data.country_name,
        state_prov: data.state_prov,
        hostname: data.hostname,
        error: ""
      });
    }
  }

  return (
    <Router>
      <div className="App">
        <Header />
        <Switch>
          <Route path="/" exact>
            <div>
              <Info />
              <Form />
              <Place
                temp={state.temp}
                ip={state.ip}
                city={state.city}
                country_name={state.country_name}
                state_prov={state.state_prov}
                hostname={state.hostname}
                error={state.error}
                gettingPlace={gettingPlace}
              />
            </div>
          </Route>
          <Route path="/login" component={Login} />
          <Route path="/register" component={Register} />
        </Switch>
        <Footer />
      </div>
    </Router>
  );
};

export default App;
